 useEffect(()=>{if(!modal&&!detail&&!quoteBuilder&&!credentials)return;const previous=document.activeElement as HTMLElement|null;const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const dialogs=document.querySelectorAll('[role="dialog"]');const dialog=dialogs[dialogs.length-1];if(!dialog)return;const focusable=Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]'));const first=focusable[0],last=focusable[focusable.length-1];if(!first)return;if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus();}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus();};},[!!modal,!!detail,!!quoteBuilder,!!credentials]);
